use crate::{features::Family,fenwick::{Table,bump}};
pub const FAMILIES:[Family;4]=[Family::Global,Family::Symbol,Family::Recent,Family::Joint];
pub const ROWS:[usize;4]=[32,16384,4096,4096];
pub fn hash(key:u32)->u32{let mut h=(key^(key>>16)).wrapping_mul(0x7feb352d);h=(h^(h>>15)).wrapping_mul(0x846ca68b);h^(h>>16)}
fn fill<T:Clone>(len:usize,value:T)->Result<Vec<T>,String>{let mut v=Vec::new();v.try_reserve_exact(len).map_err(|_|"audit allocation")?;v.resize(len,value);Ok(v)}
pub fn four_keys(component:usize,joint:u32,recent:u32)->Result<[u32;4],String>{
    if Family::Joint.component(joint)?!=component{return Err("joint component mismatch".into());}let context=((joint>>18)&15) as usize;let symbol=((joint>>9)&511) as usize;let rank_exp=((joint>>5)&7) as usize;let length_exp=(joint&31) as usize;
    let mut keys=[0;4];for i in 0..4{keys[i]=FAMILIES[i].key(component,context,symbol,recent,rank_exp,length_exp)?;}if keys[3]!=joint{return Err("joint lossless reconstruction".into());}Ok(keys)
}
pub fn valid_weights(weights:&[f64;4])->Result<(),String>{let mut sum=0.0;for &w in weights{if !w.is_finite() || w<=0.0 || w>1.0{return Err("weight finite/positive/range".into());}sum+=w;}if !sum.is_finite() || (sum-1.0).abs()>1e-12{return Err("weight sum".into());}Ok(())}
pub fn cumulative(k:usize,limit:usize,s:f64)->Result<u32,String>{if limit==0 || limit>257 || k>limit || !s.is_finite() || s<0.0 || s>1.0+1e-12{return Err("mixture cumulative input".into());}if k==0{return Ok(0);}if k==limit{return Ok(32768);}let scaled=((32768-limit) as f64*s).floor();if !scaled.is_finite() || scaled<0.0 || scaled>(32768-limit) as f64{return Err("mixture cumulative floor range".into());}let value=(k as u32).checked_add(scaled as u32).ok_or("CDF add overflow")?;if value<k as u32 || value>32768-(limit-k) as u32{return Err("CDF reserved freq bound".into());}Ok(value)}
pub struct Bank {pub table:Table,pub family:Family,pub first_key:Vec<u32>,pub collision:Vec<u8>,pub key_bitmap:Vec<u64>,pub active_rows:u64,pub distinct_keys:u64,pub alias_rows:u64,pub alias_events:u64}
impl Bank {
    fn new(i:usize)->Result<Self,String>{let family=FAMILIES[i];let rows=ROWS[i];let table=Table::new(rows)?;let first_key=fill(rows,u32::MAX)?;let collision=fill(rows,0u8)?;let key_bitmap=if i>=2{fill((1usize<<family.bits())/64,0u64)?}else{Vec::new()};Ok(Self{table,family,first_key,collision,key_bitmap,active_rows:0,distinct_keys:0,alias_rows:0,alias_events:0})}
    pub fn row(&self,key:u32)->Result<usize,String>{self.family.component(key)?;let i=if self.key_bitmap.is_empty(){key as usize}else{(hash(key)&4095) as usize};if i>=self.table.rows{return Err("expert row range".into());}Ok(i)}
    fn touch(&mut self,key:u32,row:usize)->Result<(),String>{if self.first_key[row]==u32::MAX{self.first_key[row]=key;bump(&mut self.active_rows,1)?;if self.key_bitmap.is_empty(){bump(&mut self.distinct_keys,1)?;}}else if self.first_key[row]!=key{if self.key_bitmap.is_empty(){return Err("direct row alias".into());}bump(&mut self.alias_events,1)?;if self.collision[row]==0{self.collision[row]=1;bump(&mut self.alias_rows,1)?;}}
        if !self.key_bitmap.is_empty(){let word=key as usize/64;let mask=1u64<<(key%64);if self.key_bitmap[word]&mask==0{self.key_bitmap[word]|=mask;bump(&mut self.distinct_keys,1)?;}}Ok(())}
    pub fn bytes(&self)->usize{self.table.allocation_bytes()+self.first_key.capacity()*4+self.collision.capacity()+self.key_bitmap.capacity()*8}
    pub fn json(&self)->String{let o=self.table.ops;format!("{{\"family\":\"{}\",\"rows\":{},\"active_rows\":{},\"distinct_original_keys\":{},\"distinct_keys_minus_active_rows\":{},\"aliased_rows\":{},\"events_key_differs_from_row_first_key\":{},\"leaf_len\":{},\"leaf_capacity\":{},\"tree_len\":{},\"tree_capacity\":{},\"total_capacity\":{},\"first_key_capacity\":{},\"collision_capacity\":{},\"key_bitmap_capacity_words\":{},\"allocation_bytes\":{},\"prefix_queries\":{},\"prefix_visits\":{},\"token_updates\":{},\"update_visits\":{},\"rescales\":{},\"rebuild_leaves\":{},\"rebuild_visits\":{}}}",self.family.name(),self.table.rows,self.active_rows,self.distinct_keys,self.distinct_keys-self.active_rows,self.alias_rows,self.alias_events,self.table.leaf.len(),self.table.leaf.capacity(),self.table.tree.len(),self.table.tree.capacity(),self.table.total.capacity(),self.first_key.capacity(),self.collision.capacity(),self.key_bitmap.capacity(),self.bytes(),o.queries,o.query_visits,o.updates,o.update_visits,o.rescales,o.rebuild_leaves,o.rebuild_visits)}
}
pub struct Prediction {pub keys:[u32;4],pub rows:[usize;4],pub global:usize,pub token:usize,pub limit:usize,pub probabilities:[f64;4],pub old_weights:[f64;4],pub mixture_probability:f64,pub low:u32,pub high:u32}
pub struct Mix {pub banks:[Bank;4],pub weights:[[f64;4];32],pub observations:u64}
impl Mix {
    pub fn new()->Result<Self,String>{Ok(Self{banks:[Bank::new(0)?,Bank::new(1)?,Bank::new(2)?,Bank::new(3)?],weights:[[0.25;4];32],observations:0})}
    pub fn predict(&mut self,keys:[u32;4],token:usize,limit:usize)->Result<Prediction,String>{
        if limit==0 || limit>257 || token>=limit{return Err("prediction token/limit".into());}let global=keys[0] as usize;if global>=32{return Err("prediction global key".into());}
        for i in 0..4{FAMILIES[i].component(keys[i])?;if keys[i]>>(FAMILIES[i].bits()-5)!=keys[0]{return Err("expert context mismatch".into());}}
        if keys[1]&511>=257 || four_keys(Family::Joint.component(keys[3])?,keys[3],keys[2]&65535)?!=keys{return Err("expert key fields".into());}
        let weights=self.weights[global];valid_weights(&weights)?;let mut rows=[0;4];let mut probabilities=[0.0;4];let mut slo=0.0;let mut shi=0.0;let mut mixture_probability=0.0;
        for i in 0..4{let bank=&mut self.banks[i];let row=bank.row(keys[i])?;rows[i]=row;let total=bank.table.prefix(row,limit)?;let lower=bank.table.prefix(row,token)?;let count=bank.table.count(row,token)?;let upper=lower.checked_add(count).ok_or("expert upper overflow")?;if total==0 || upper>total || lower>=upper{return Err("expert prefix interval".into());}let p=count as f64/total as f64;if !p.is_finite() || p<=0.0 || p>1.0{return Err("expert probability".into());}probabilities[i]=p;slo+=weights[i]*(lower as f64/total as f64);shi+=weights[i]*(upper as f64/total as f64);mixture_probability+=weights[i]*p;}
        if !mixture_probability.is_finite() || mixture_probability<=0.0 || mixture_probability>1.0+1e-12{return Err("mixture probability".into());}let low=cumulative(token,limit,slo)?;let high=cumulative(token+1,limit,shi)?;if low>=high || high>32768{return Err("quantized actual interval".into());}
        Ok(Prediction{keys,rows,global,token,limit,probabilities,old_weights:weights,mixture_probability,low,high})
    }
    pub fn observe(&mut self,prediction:Prediction)->Result<(),String>{if self.weights[prediction.global].map(f64::to_bits)!=prediction.old_weights.map(f64::to_bits){return Err("diagnostic stale weights".into());}let mut next=[0.0;4];for i in 0..4{let posterior=prediction.old_weights[i]*prediction.probabilities[i]/prediction.mixture_probability;if !posterior.is_finite() || posterior<=0.0 || posterior>1.0+1e-12{return Err("posterior finite/range".into());}next[i]=(255.0/256.0)*posterior+1.0/1024.0;}valid_weights(&next)?;
        for i in 0..4{self.banks[i].table.observe(prediction.rows[i],prediction.token)?;self.banks[i].touch(prediction.keys[i],prediction.rows[i])?;}self.weights[prediction.global]=next;bump(&mut self.observations,1)?;Ok(())}
    pub fn bytes(&self)->usize{self.banks.iter().map(Bank::bytes).sum::<usize>()+std::mem::size_of_val(&self.weights)}
    pub fn verify_terminal(&self)->Result<usize,String>{let mut cells=0;for bank in &self.banks{cells+=bank.table.verify_all()?;let active=bank.first_key.iter().filter(|&&k|k!=u32::MAX).count() as u64;let aliases=bank.collision.iter().filter(|&&b|b!=0).count() as u64;if active!=bank.active_rows || aliases!=bank.alias_rows || bank.distinct_keys<active{return Err("terminal alias counters".into());}if !bank.key_bitmap.is_empty() && bank.key_bitmap.iter().map(|w|w.count_ones() as u64).sum::<u64>()!=bank.distinct_keys{return Err("terminal distinct bitmap".into());}}for w in &self.weights{valid_weights(w)?;}Ok(cells)}
}
